-- Sandra Sullivan (profileID=19) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Sandra Sullivan phrasings

SELECT p.argumentID, p.phrasingID, 19, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 19
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 19 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=19 AND targArgID IN (80,88,89,90,91,92,93,94,96,97,103,104,105,110,120,123,137,145,148,151,153,154,155,169,175,182,184,193,217,219,221,230,288,321,346,347,349,355,356,357,383,384,386,387,389,414,422,434,435,441,456,457,469,470,476,494,495,496,539,546,547,561,574,597,640,696,698,745,756,770,863,864,866,894,895,896,897,898,909,958,1005,1200,1201,1202,1275,1313);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 19
SET pe.active = o.acceptance
WHERE pe.profileID = 19;

SELECT 'Done: endorsements for profileID=19' AS status;